import {CHALLENGE_IDS,CATEGORY_LABELS,safeUrl,parseImport,mergeMessages,summarize,csv,equalChanceTopThree} from './model.js';
const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const names=['Rev’s Casino','Dashboard Royale','Build-A-Dataset','House Edge','Heads Up – Poker Bot Tournament','Hitachi: Hack the Highway','HEB Challenge','Best Use of Databricks'];
let catalog=CHALLENGE_IDS.map((id,i)=>({id,name:names[i]})),messages=[],observationData={metadata:{},records:[]},messageData={metadata:{}},localMessages=[];
const storageKey='challenge-pulse-discord-v1';let toastTimer;
function showNotice(text){$('load-notice').textContent=text;$('load-notice').hidden=false;}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,4500);}
function showPanel(id){if(!['overview','explore','evidence','scenario','simulation'].includes(id))id='overview';document.querySelectorAll('.panel').forEach(p=>{p.hidden=p.id!==id;p.classList.toggle('active',p.id===id);});document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.panel===id);if(b.dataset.panel===id)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');});history.replaceState(null,'','#'+id);window.scrollTo({top:0,behavior:'instant'});}
document.querySelectorAll('[data-panel],[data-go]').forEach(b=>b.addEventListener('click',()=>showPanel(b.dataset.panel??b.dataset.go)));
document.querySelectorAll('.brand').forEach(a=>a.addEventListener('click',e=>{e.preventDefault();showPanel('overview');}));
window.addEventListener('hashchange',()=>showPanel(location.hash.slice(1)));
const challengeName=id=>catalog.find(c=>c.id===id)?.name??id;
function selectMessages(){const id=$('challenge-filter').value;return id==='all'?messages:messages.filter(r=>r.challenge_id===id);}
function coverageRecords(){return CHALLENGE_IDS.map(id=>{const base=observationData.records.find(r=>r.challenge_id===id)??{challenge_id:id,coverage_status:'not_read',coverage_note:'Channel not read. Activity is unknown.'};const rows=messages.filter(r=>r.challenge_id===id),imported=localMessages.filter(r=>r.challenge_id===id);if(!rows.length)return{...base,observed_messages:null,distinct_display_labels:null,category_counts:null};return{...base,...(imported.length?{displayed_date:null,first_displayed_time:null,last_displayed_time:null,window_start:null,window_end:null,display_label_message_counts:null,largest_display_label_message_share:null,concentration_note:null,captured_at:null,timezone:null}:{}),coverage_status:'partial',observed_messages:rows.length,distinct_display_labels:imported.length?null:base.distinct_display_labels??null,category_counts:summarize(rows).category_counts,coverage_note:imported.length?'Partial message samples merged on this device. Identity aliases and coverage intervals may differ across samples; no combined observation window is established.':base.coverage_note,messages_per_hour:null,team_count:null,entrant_count:null};});}
function renderOverview(){const rows=selectMessages(),stats=summarize(rows),selected=$('challenge-filter').value,selectedCoverage=coverageRecords().filter(r=>selected==='all'||r.challenge_id===selected),read=selectedCoverage.filter(r=>r.coverage_status==='partial').length;
 const labels=selectedCoverage.length===1?selectedCoverage[0].distinct_display_labels:stats.channels===1?selectedCoverage.find(r=>r.observed_messages!==null)?.distinct_display_labels:null;
 const pct=stats.messages?Math.round(stats.leaderboard_requests/stats.messages*100):null;
 const cards=[['Observed messages',stats.messages||'—',stats.messages?'Distinct message IDs in this sample':'No observed message records','▤'],['Channels with observations',`${read} / ${selectedCoverage.length}`,'Partial coverage, not a channel census','◎'],['Display labels',labels??'—',labels!==null&&labels!==undefined?'Visible labels in the original sample; not teams':'Not comparable or not observed','◇'],['Leaderboard requests',stats.messages?stats.leaderboard_requests:'—',stats.messages?`${pct}% of ${stats.messages} observed messages`:'No sample denominator','↗']];
 $('metrics').innerHTML=cards.map(([label,value,detail,icon])=>`<div class="metric"><span class="metric-label">${esc(label)}</span><span class="metric-icon" aria-hidden="true">${icon}</span><strong class="metric-value">${esc(value)}</strong><span class="metric-detail">${esc(detail)}</span></div>`).join('');
 $('filter-caption').textContent=stats.messages?`${stats.messages} observed messages · ${stats.channels} sampled channel${stats.channels===1?'':'s'}`:'No messages observed for this selection';
 $('coverage-title').textContent=read?`${read} channel${read===1?' has':'s have'} a partial sample. ${selectedCoverage.length-read} remain${selectedCoverage.length-read===1?'s':''} unread.`:'This channel has not been read.';
 $('coverage-copy').textContent='Missing activity is unknown, not zero. The visible sample does not establish full time coverage, participant counts or competitive intensity.';
 const entries=Object.entries(stats.category_counts).sort((a,b)=>b[1]-a[1]);
 $('category-chart').innerHTML=entries.length?entries.map(([key,n])=>`<div class="chart-row"><span class="chart-label" title="${esc(CATEGORY_LABELS[key])}">${esc(CATEGORY_LABELS[key])}</span><div class="chart-track"><div class="chart-bar" style="width:${n/stats.messages*100}%"></div></div><span class="chart-value">${n} · ${Math.round(n/stats.messages*100)}%</span></div>`).join(''):'<p class="not-observed">No sampled messages for this challenge. No category share can be calculated.</p>';
 $('sample-insight').innerHTML=stats.leaderboard_requests?`<div class="insight-number">${pct}<span>%</span></div><h3>Asked for a leaderboard</h3><p class="insight-copy">${stats.leaderboard_requests} of ${stats.messages} messages in this selected sample explicitly request a leaderboard or an update.</p><div class="insight-action"><span class="eyebrow">POSSIBLE RESPONSE</span><p>An up-to-date leaderboard may answer recurring requests. This is a sample finding, not evidence that all participants need one.</p></div><button class="text-button" id="show-leaderboard">Inspect these messages ↗</button>`:stats.messages?'<h3>No leaderboard request in this sample</h3><p class="insight-copy">That means none was coded among these messages. It does not establish that no one in the channel requested one.</p>':'<h3>Observe before drawing a conclusion</h3><p class="insight-copy">This selection has no coded messages. Import an observed sample to inspect content patterns.</p>';
 $('show-leaderboard')?.addEventListener('click',()=>{$('explore-challenge').value=selected;$('category-filter').value='leaderboard_request';$('message-search').value='';renderExplorer();showPanel('explore');});
}
function renderCatalog(){const symbols=['♠','▥','✦','♦','♣','↗','♥','◈'];$('catalog').innerHTML=catalog.map((c,i)=>{const link=safeUrl(c.page_url??c.source_url),prize=Array.isArray(c.prizes)?c.prizes[0]:c.prizes?.['1'];return`<article class="challenge-card"><div class="challenge-top"><span class="challenge-symbol" aria-hidden="true">${symbols[i]??'✦'}</span><span class="challenge-index">0${i+1}</span></div><h3>${esc(c.name)}</h3><p>${esc(c.objective??c.summary??'Official challenge information is not loaded.')}</p><span class="prize-label">FIRST PLACE · OFFICIAL LISTING</span><div class="challenge-prize">${esc(prize??'See official challenge details')}</div>${link?`<a class="text-link" href="${esc(link)}" target="_blank" rel="noopener">Challenge details <span>↗</span></a>`:'<span class="small-note">Source unavailable</span>'}</article>`;}).join('');}
function renderExplorer(){const id=$('explore-challenge').value,category=$('category-filter').value,query=$('message-search').value.trim().toLowerCase();const rows=messages.filter(r=>(id==='all'||r.challenge_id===id)&&(category==='all'||r.category===category)&&(!query||r.paraphrase.toLowerCase().includes(query)));$('message-count').textContent=`${rows.length} of ${messages.length} observed messages`;$('messages-body').innerHTML=rows.length?rows.map(r=>`<tr><td><strong>${esc(r.display_time)}</strong><small>${esc(r.display_date)}</small><small>${esc(r.timezone??'Timezone unverified')}</small></td><td>${esc(challengeName(r.challenge_id))}</td><td><span class="alias-badge">${esc(r.display_alias)}</span></td><td><span class="category-tag">${esc(CATEGORY_LABELS[r.category])}</span></td><td class="message-paraphrase">${esc(r.paraphrase)}</td><td><a class="text-link" href="${esc(safeUrl(r.source_url))}" target="_blank" rel="noopener">Message ↗</a></td></tr>`).join(''):'<tr><td colspan="6" class="empty-table">No observed messages match these filters.</td></tr>';}
function renderEvidence(){const records=coverageRecords();$('discord-method').textContent=localMessages.length?'Mixed partial samples: bundled observations plus imported coded messages. Imports have not been independently verified; no combined observation window is established.':observationData.metadata?.sampling??'Partial UI observations; no complete channel history or complete time interval.';$('discord-limits').textContent='No messages-per-hour calculation or cross-challenge ranking is supported by this coverage. Missing fields remain null in exported data.';$('discord-snapshots').innerHTML=records.map(r=>{const partial=r.coverage_status==='partial',link=safeUrl(r.source_url);return`<article class="discord-card"><div class="discord-card-header"><h3>${esc(challengeName(r.challenge_id))}</h3><span class="source-pill neutral">${partial?'Partial sample':'Not read'}</span></div><div class="discord-window">${partial?esc(r.displayed_date??'Imported sample')+' · '+esc(r.first_displayed_time??'Unknown start')+'–'+esc(r.last_displayed_time??'unknown end')+' · timezone unverified':'No messages observed. Channel activity is unknown.'}</div><div class="discord-numbers"><div><strong>${r.observed_messages??'—'}</strong><small>Observed messages</small></div><div><strong>${r.distinct_display_labels??'—'}</strong><small>Display labels · not teams</small></div></div>${partial?`<ul class="theme-list">${Object.entries(r.category_counts??{}).map(([k,n])=>`<li>${esc(CATEGORY_LABELS[k]??k)} · ${n}</li>`).join('')}</ul>`:''}<p>${esc(r.coverage_note)}</p>${link?`<a class="text-link" href="${esc(link)}" target="_blank" rel="noopener">Open channel ↗</a>`:''}</article>`;}).join('');}
function renderAll(){renderOverview();renderCatalog();renderExplorer();renderEvidence();$('footer-data-status').textContent=`${messages.length} observed messages · ${summarize(messages).channels} of 8 channels sampled`;}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function exportMetadata(base){return localMessages.length?{source_type:'discord_ui_observation',sampling:'Mixed partial message samples: bundled observations plus user-imported coded records. No complete channel or interval coverage is established.',collection_method:'Bundled assistant UI observations and imported message records; imported records have not been independently verified.',captured_at:null,display_timezone:null,imported_on_this_device:localMessages.length,identity_note:'Aliases may collide across samples. No combined distinct-display-label count is reported.',seed_metadata:base}:{...base,imported_on_this_device:0};}
document.querySelectorAll('[data-export]').forEach(b=>b.addEventListener('click',()=>{const kind=b.dataset.export;const exported_at=new Date().toISOString();if(kind==='messages-csv')download('challenge-pulse-messages.csv',csv(messages),'text/csv;charset=utf-8');else if(kind==='coverage-json')download('challenge-pulse-coverage.json',JSON.stringify({...observationData,metadata:exportMetadata(observationData.metadata),exported_at,records:coverageRecords()},null,2),'application/json');else download('challenge-pulse-messages.json',JSON.stringify({...messageData,schema_version:1,exported_at,metadata:exportMetadata(messageData.metadata),records:messages},null,2),'application/json');}));
$('import-file').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;const box=$('import-message');try{if(file.size>5*1024*1024)throw new Error('Choose a file smaller than 5 MB.');const input=parseImport(JSON.parse(await file.text())),merged=mergeMessages(messages,input);const baseIds=new Set(messages.filter(r=>!localMessages.some(l=>l.message_id===r.message_id)).map(r=>r.message_id));const nextLocal=merged.records.filter(r=>!baseIds.has(r.message_id));try{localStorage.setItem(storageKey,JSON.stringify({schema_version:1,records:nextLocal}));}catch{throw new Error('Browser storage is unavailable or full. Nothing was imported.');}messages=merged.records;localMessages=nextLocal;box.textContent=`Merged ${merged.added} new messages; skipped ${merged.skipped} duplicates. Coverage remains partial.`;box.classList.remove('error');renderAll();toast('Message sample merged.');}catch(error){box.textContent=error.message;box.classList.add('error');}box.hidden=false;e.target.value='';});
document.querySelector('.import-button').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();$('import-file').click();}});
$('challenge-filter').addEventListener('change',renderOverview);$('explore-challenge').addEventListener('change',renderExplorer);$('category-filter').addEventListener('change',renderExplorer);$('message-search').addEventListener('input',renderExplorer);
$('scenario-form').addEventListener('submit',e=>e.preventDefault());$('entrant-count').addEventListener('input',()=>{const raw=$('entrant-count').value,n=Number(raw),v=raw?equalChanceTopThree(n):null;$('scenario-result').innerHTML=v===null?'<span class="scenario-number">—</span><span>Enter a whole number from 1 to 100,000.</span>':`<span class="scenario-number">${(100*v).toLocaleString(undefined,{maximumFractionDigits:1})}%</span><span>Hypothetical equal-chance baseline · ${n.toLocaleString()} assumed entrants</span>`;});
async function load(){const results=await Promise.allSettled(['catalog.json','discord-observations.json','discord-message-coding.json'].map(async f=>{const r=await fetch('./data/'+f);if(!r.ok)throw new Error(`${f}: HTTP ${r.status}`);return r.json();}));const errors=[];if(results[0].status==='fulfilled'&&Array.isArray(results[0].value.challenges)){catalog=results[0].value.challenges.map(c=>({...c,id:c.id??c.challenge_id}));}else errors.push('The official catalog could not be loaded.');if(results[1].status==='fulfilled'&&Array.isArray(results[1].value.records))observationData=results[1].value;else errors.push('Coverage metadata could not be loaded.');if(results[2].status==='fulfilled'){try{messageData=results[2].value;messages=mergeMessages([],parseImport(messageData)).records;}catch(e){errors.push('Message data: '+e.message);}}else errors.push('The message dataset could not be loaded.');try{const stored=localStorage.getItem(storageKey);if(stored){localMessages=parseImport(JSON.parse(stored));messages=mergeMessages(messages,localMessages).records;}}catch(e){localMessages=[];errors.push('Saved local imports could not be loaded: '+e.message);}for(const id of ['challenge-filter','explore-challenge'])$(id).innerHTML='<option value="all">All challenges</option>'+catalog.map(c=>`<option value="${esc(c.id)}">${esc(c.name)}</option>`).join('');$('category-filter').innerHTML='<option value="all">All categories</option>'+Object.entries(CATEGORY_LABELS).map(([k,v])=>`<option value="${k}">${esc(v)}</option>`).join('');if(errors.length)showNotice(errors.join(' ')+' Run this app with node serve.mjs, rather than opening index.html as a file.');renderAll();showPanel(location.hash.slice(1));}
load().catch(error=>showNotice('The dashboard could not initialize: '+error.message));
